-- MySQL 8.0.16+
-- IDs are generated by the Go application as UUID strings.
-- JSON is used for flexible Agent payloads and embeddings.

CREATE TABLE customers (
    id CHAR(36) NOT NULL,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(320),
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE projects (
    id CHAR(36) NOT NULL,
    customer_id CHAR(36),
    name VARCHAR(255) NOT NULL,
    status VARCHAR(64) NOT NULL DEFAULT 'draft',
    current_round INT NOT NULL DEFAULT 0,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_projects_customer (customer_id),
    CONSTRAINT fk_projects_customer FOREIGN KEY (customer_id) REFERENCES customers(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE briefs (
    id CHAR(36) NOT NULL,
    project_id CHAR(36) NOT NULL,
    product_info JSON NOT NULL,
    brand_info JSON NOT NULL,
    audience VARCHAR(500),
    market VARCHAR(255),
    package_spec JSON NOT NULL,
    material VARCHAR(255),
    printing_process VARCHAR(255),
    required_text JSON NOT NULL,
    constraints_json JSON NOT NULL,
    completion_score INT NOT NULL DEFAULT 0,
    version INT NOT NULL DEFAULT 1,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_briefs_project (project_id, version),
    CONSTRAINT chk_briefs_completion CHECK (completion_score BETWEEN 0 AND 100),
    CONSTRAINT fk_briefs_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE assets (
    id CHAR(36) NOT NULL,
    project_id CHAR(36) NOT NULL,
    asset_type VARCHAR(64) NOT NULL,
    storage_url LONGTEXT NOT NULL,
    width INT,
    height INT,
    prompt TEXT,
    provider VARCHAR(128),
    model VARCHAR(128),
    version INT NOT NULL DEFAULT 1,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_assets_project (project_id, created_at),
    CONSTRAINT fk_assets_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE design_proposals (
    id CHAR(36) NOT NULL,
    project_id CHAR(36) NOT NULL,
    round_no INT NOT NULL,
    title VARCHAR(255) NOT NULL,
    concept TEXT NOT NULL,
    design_strategy JSON NOT NULL,
    color_palette JSON NOT NULL,
    typography VARCHAR(255),
    difference_summary TEXT,
    status VARCHAR(64) NOT NULL DEFAULT 'draft',
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_proposals_project_round (project_id, round_no),
    CONSTRAINT fk_proposals_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE proposal_assets (
    proposal_id CHAR(36) NOT NULL,
    asset_id CHAR(36) NOT NULL,
    PRIMARY KEY (proposal_id, asset_id),
    CONSTRAINT fk_proposal_assets_proposal FOREIGN KEY (proposal_id) REFERENCES design_proposals(id) ON DELETE CASCADE,
    CONSTRAINT fk_proposal_assets_asset FOREIGN KEY (asset_id) REFERENCES assets(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE feedback (
    id CHAR(36) NOT NULL,
    project_id CHAR(36) NOT NULL,
    proposal_id CHAR(36),
    rating TINYINT,
    comment TEXT,
    liked_items JSON NOT NULL,
    disliked_items JSON NOT NULL,
    must_change JSON NOT NULL,
    optional_change JSON NOT NULL,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_feedback_project (project_id, created_at),
    CONSTRAINT chk_feedback_rating CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
    CONSTRAINT fk_feedback_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    CONSTRAINT fk_feedback_proposal FOREIGN KEY (proposal_id) REFERENCES design_proposals(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE agent_runs (
    id CHAR(36) NOT NULL,
    project_id CHAR(36) NOT NULL,
    agent_type VARCHAR(64) NOT NULL,
    round_no INT NOT NULL DEFAULT 0,
    input_json JSON NOT NULL,
    output_json JSON,
    status VARCHAR(64) NOT NULL DEFAULT 'queued',
    error_message TEXT,
    provider VARCHAR(128),
    model VARCHAR(128),
    input_tokens INT,
    output_tokens INT,
    duration_ms BIGINT,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    completed_at DATETIME(3),
    PRIMARY KEY (id),
    KEY idx_agent_runs_project (project_id, created_at),
    CONSTRAINT fk_agent_runs_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE project_documents (
    id CHAR(36) NOT NULL,
    project_id CHAR(36) NOT NULL,
    document_type VARCHAR(64) NOT NULL,
    storage_url LONGTEXT NOT NULL,
    version INT NOT NULL DEFAULT 1,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_documents_project (project_id, created_at),
    CONSTRAINT fk_documents_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE knowledge_documents (
    id CHAR(36) NOT NULL,
    title VARCHAR(255) NOT NULL,
    content LONGTEXT NOT NULL,
    metadata JSON NOT NULL,
    embedding JSON,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_knowledge_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
